use std::fs

struct Tree {
    keys: Vec<int>,
    lefts: Vec<int>,
    rights: Vec<int>,
    root: int,
}

impl Tree {
    fn contains(self, x: int) -> bool {
        let mut cur = self.root
        while cur != -1 {
            let k = self.keys[cur]
            if x == k {
                return true
            }
            if x < k { cur = self.lefts[cur] } else { cur = self.rights[cur] }
        }
        false
    }

    fn insert(self, x: int) {
        let id = self.keys.len()
        self.keys.push(x)
        self.lefts.push(-1)
        self.rights.push(-1)
        if self.root == -1 {
            self.root = id
            return
        }
        let mut cur = self.root
        loop {
            if x < self.keys[cur] {
                if self.lefts[cur] == -1 {
                    self.lefts[cur] = id
                    return
                }
                cur = self.lefts[cur]
            } else {
                if self.rights[cur] == -1 {
                    self.rights[cur] = id
                    return
                }
                cur = self.rights[cur]
            }
        }
    }

    fn remove(self, x: int) {
        let mut p = -1
        let mut n = self.root
        while n != -1 && self.keys[n] != x {
            p = n
            if x < self.keys[n] { n = self.lefts[n] } else { n = self.rights[n] }
        }
        if self.lefts[n] != -1 && self.rights[n] != -1 {
            let mut sp = n
            let mut s = self.rights[n]
            while self.lefts[s] != -1 {
                sp = s
                s = self.lefts[s]
            }
            self.keys[n] = self.keys[s]
            if sp == n {
                self.rights[sp] = self.rights[s]
            } else {
                self.lefts[sp] = self.rights[s]
            }
        } else {
            let c = if self.lefts[n] != -1 { self.lefts[n] } else { self.rights[n] }
            if p == -1 {
                self.root = c
            } else if self.lefts[p] == n {
                self.lefts[p] = c
            } else {
                self.rights[p] = c
            }
        }
    }

    fn inorder(self) -> Vec<int> {
        let mut out: Vec<int> = []
        let mut stack: Vec<int> = []
        let mut cur = self.root
        while cur != -1 || stack.len() > 0 {
            while cur != -1 {
                stack.push(cur)
                cur = self.lefts[cur]
            }
            let top = stack.pop().unwrap_or(-1)
            out.push(self.keys[top])
            cur = self.rights[top]
        }
        out
    }

    fn height(self) -> int {
        if self.root == -1 {
            return 0
        }
        let mut best = 0
        let mut nodes: Vec<int> = [self.root]
        let mut depths: Vec<int> = [1]
        while nodes.len() > 0 {
            let n = nodes.pop().unwrap_or(-1)
            let d = depths.pop().unwrap_or(0)
            if d > best { best = d }
            if self.lefts[n] != -1 {
                nodes.push(self.lefts[n])
                depths.push(d + 1)
            }
            if self.rights[n] != -1 {
                nodes.push(self.rights[n])
                depths.push(d + 1)
            }
        }
        best
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Tree { keys: [], lefts: [], rights: [], root: -1 }
    for line in text.lines() {
        let parts: Vec<string> = line.trim().split(" ").collect()
        let cmd = parts[0]
        if cmd == "insert" {
            let x = parts[1].parse::<int>().unwrap_or(0)
            if t.contains(x) {
                println("dup")
            } else {
                t.insert(x)
                println("ok")
            }
        } else if cmd == "contains" {
            let x = parts[1].parse::<int>().unwrap_or(0)
            if t.contains(x) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let x = parts[1].parse::<int>().unwrap_or(0)
            if t.contains(x) {
                t.remove(x)
                println("ok")
            } else {
                println("missing")
            }
        } else if cmd == "inorder" {
            let v = t.inorder()
            if v.len() == 0 {
                println("<empty>")
            } else {
                let strs: Vec<string> = v.map(|k| "${k}").collect()
                println(strs.join(" "))
            }
        } else if cmd == "height" {
            println("${t.height()}")
        } else if cmd == "min" {
            let v = t.inorder()
            if v.len() == 0 { println("empty") } else { println("${v[0]}") }
        } else if cmd == "max" {
            let v = t.inorder()
            if v.len() == 0 { println("empty") } else { println("${v[v.len() - 1]}") }
        }
    }
}

